export async function buildPrompt({ root, sources, common, scenario, variant, cwd, browserPaths }) {
  const keys = variant === 'v31' ? [scenario.originalSource] : [scenario.localRoot, ...scenario.references];
  const instructions = [];
  for (const key of keys) {
