const definitions = [
  ["qs-design-frontend", "QS Design Frontend", "Build or revise a frontend within its existing constraints", "build or revise this selected frontend while preserving its authorized scope", ["brief", "design-direction", "redesign", "dimensional-style", "restrained-style", "implementation", "cinematic-landing", "motion-recipes", "media-recipes"]],
  ["qs-design-image-web", "QS Design Image Web", "Create web design images or reusable design prompts", "create the requested web design images or prompt-only output", ["brief", "design-direction", "prompt-construction", "web-images"]],
