import {
  NEXT_SKILLS_BY_NAME,
  V3_CORE_SKILLS,
  V3_SPECIALIST_SKILLS,
} from "./qs-skill-catalog.mjs";
import {
  PS_COLLECTION,
  PS_PUBLIC_COMMANDS,
